<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Rekap absensi';$items=$pdo->query("SELECT a.id,a.nama,a.kelas,a.status AS status_anggota,COALESCE(SUM(ab.status='hadir'),0) AS hadir,COALESCE(SUM(ab.status='izin'),0) AS izin,COALESCE(SUM(ab.status='sakit'),0) AS sakit,COALESCE(SUM(ab.status='alpa'),0) AS alpa,COUNT(ab.id) AS total FROM anggota a LEFT JOIN absensi ab ON ab.anggota_id=a.id WHERE a.status='aktif' GROUP BY a.id,a.nama,a.kelas,a.status ORDER BY a.kelas,a.nama")->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Ringkasan kehadiran anggota dari seluruh sesi absensi.</p><a class="button button-outline" href="<?=osis_e(osis_url('admin/absensi/index.php'))?>">← Daftar sesi</a></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Anggota</th><th>Total sesi tercatat</th><th>Hadir</th><th>Izin</th><th>Sakit</th><th>Alpa</th><th>Persentase hadir</th></tr></thead><tbody><?php if($items):foreach($items as $item):$percent=(int)$item['total']?round((int)$item['hadir']/(int)$item['total']*100):0;?><tr><td><strong><?=osis_e($item['nama'])?></strong><small class="table-subtext"><?=osis_e($item['kelas']?:'')?></small></td><td><?=(int)$item['total']?></td><td><span class="attendance-number attendance-hadir"><?=(int)$item['hadir']?></span></td><td><?=(int)$item['izin']?></td><td><?=(int)$item['sakit']?></td><td><?=(int)$item['alpa']?></td><td><div class="attendance-meter"><span><i style="width:<?=$percent?>%"></i></span><b><?=$percent?>%</b></div></td></tr><?php endforeach;else:?><tr><td colspan="7" class="empty-inline">Belum ada anggota aktif.</td></tr><?php endif;?></tbody></table></div></div>
<?php osis_admin_page_end(); ?>
